(() => {
  'use strict';

  // Shared grass-footprint filtering for farm, town, and authored wilderness
  // buildings. Grass stays generated by its existing builders; this module
  // only compacts billboard instance matrices whose centers land inside an
  // authoritative building footprint. Keeping immutable source matrices lets
  // moved/demolished farm buildings reveal the original grass again instead
  // of permanently deleting those instances.
  if (typeof window === 'undefined' || typeof THREE === 'undefined') return;

  const localMatrix = new THREE.Matrix4(); // Reused while reading/writing one billboard instance matrix.
  const worldMatrix = new THREE.Matrix4(); // Reused to resolve an instance center through its mesh transform.
  const worldPos = new THREE.Vector3(); // Reused to convert billboard instance centers into footprint tile keys.
  let townDeps = null; // Captured TownZoneBuildings dependencies; supplies the active town scene/layout.
  let zoneDeps = null; // Captured ZoneGrassBillboards dependencies; resolves wilderness scenes back to layouts.

  const keyOf = (c, r) => `${c},${r}`;

  function rectFootprintKeys(rects) {
    const keys = new Set(); // Exact farm-building rectangle cells filtered from grass billboards.
    for (const rect of (Array.isArray(rects) ? rects : [])) {
      const col = Math.trunc(Number(rect?.col));
      const row = Math.trunc(Number(rect?.row));
      const w = Math.max(0, Math.trunc(Number(rect?.w)));
      const h = Math.max(0, Math.trunc(Number(rect?.h)));
      if (!Number.isFinite(col) || !Number.isFinite(row) || !w || !h) continue;
      for (let r = row; r < row + h; r++) {
        for (let c = col; c < col + w; c++) keys.add(keyOf(c, r));
      }
    }
    return keys;
  }

  function authoredBuildingFootprintKeys(mapData) {
    const keys = new Set(); // Rotated authored building footprint cells filtered from town/zone grass.
    const elevation = window.BuildingSubtleElevation; // Existing footprint math keeps grass and collision/elevation shapes identical.
    for (const building of (Array.isArray(mapData?.buildings) ? mapData.buildings : [])) {
      if (typeof elevation?.worldFootprintCells === 'function') {
        for (const cell of elevation.worldFootprintCells(building)) keys.add(keyOf(cell.c, cell.r));
        continue;
      }
      const width = Math.max(1, Math.round(Number(building?.footprintW) || 1));
      const depth = Math.max(1, Math.round(Number(building?.footprintD) || 1));
      const col = Math.round(Number(building?.gridX) || 0);
      const row = Math.round(Number(building?.gridZ) || 0);
      for (let r = row; r < row + depth; r++) for (let c = col; c < col + width; c++) keys.add(keyOf(c, r));
    }
    return keys;
  }

  function isGrassBillboardMesh(mesh) {
    return !!(mesh?.isInstancedMesh && mesh.userData?.isBillboard === true && mesh.instanceMatrix?.array);
  }

  function _cacheNames(cacheKey) {
    const stem = String(cacheKey || 'hobunjiBuildingGrass'); // Stable userData prefix keeps independent scene filters from overwriting each other.
    return {
      matrices: `${stem}BaseMatrices`,
      count: `${stem}BaseCount`,
      capacity: `${stem}BaseCapacity`,
    };
  }

  function filterBillboardMesh(mesh, blockedKeys, cacheKey) {
    if (!isGrassBillboardMesh(mesh)) return { source: 0, visible: 0, suppressed: 0 };
    const names = _cacheNames(cacheKey); // Cache property names for this caller's immutable source matrices.
    const capacity = mesh.instanceMatrix.array.length; // Current matrix-buffer length detects rebuilt InstancedMeshes.
    if (!mesh.userData[names.matrices] || mesh.userData[names.capacity] !== capacity) {
      mesh.userData[names.matrices] = new Float32Array(mesh.instanceMatrix.array);
      mesh.userData[names.count] = mesh.count;
      mesh.userData[names.capacity] = capacity;
    }

    const base = mesh.userData[names.matrices]; // Original unfiltered matrices used to restore grass after a footprint moves.
    const sourceCount = Math.min(Number(mesh.userData[names.count]) || 0, Math.floor(base.length / 16));
    mesh.updateMatrixWorld(true);
    let write = 0; // Next visible output slot while compacting around blocked building cells.
    let suppressed = 0; // Number of grass instances omitted because their center is inside a footprint.

    for (let i = 0; i < sourceCount; i++) {
      localMatrix.fromArray(base, i * 16);
      worldMatrix.multiplyMatrices(mesh.matrixWorld, localMatrix);
      worldPos.setFromMatrixPosition(worldMatrix);
      const cellKey = keyOf(Math.floor(worldPos.x), Math.floor(worldPos.z));
      if (blockedKeys?.has(cellKey)) {
        suppressed++;
        continue;
      }
      mesh.setMatrixAt(write++, localMatrix);
    }

    mesh.count = write;
    mesh.instanceMatrix.needsUpdate = true;
    mesh.computeBoundingBox?.();
    mesh.computeBoundingSphere?.();
    return { source: sourceCount, visible: write, suppressed };
  }

  function filterObject(root, blockedKeys, cacheKey) {
    const stats = { meshes: 0, source: 0, visible: 0, suppressed: 0 }; // Aggregate used by mobile/debug snapshots and concise runtime logs.
    if (!root) return stats;
    root.updateMatrixWorld?.(true);
    const visit = obj => {
      if (!isGrassBillboardMesh(obj)) return;
      const result = filterBillboardMesh(obj, blockedKeys, cacheKey);
      stats.meshes++;
      stats.source += result.source;
      stats.visible += result.visible;
      stats.suppressed += result.suppressed;
    };
    if (typeof root.traverse === 'function') root.traverse(visit);
    else visit(root);
    return stats;
  }

  function filterScene(scene, blockedKeys, cacheKey) {
    return filterObject(scene, blockedKeys, cacheKey);
  }

  function _patchSceneAdd(scene, getBlockedKeys, cacheKey) {
    if (!scene || scene.userData?.[`${cacheKey}SceneAddPatched`]) return;
    scene.userData = scene.userData || {};
    const originalAdd = scene.add; // Existing scene.add implementation chained so terrain/elevation hooks keep working.
    scene.add = function (...objects) {
      const result = originalAdd.apply(this, objects);
      queueMicrotask(() => {
        const blocked = getBlockedKeys(); // Latest footprints are sampled after the object actually enters the scene graph.
        for (const obj of objects) filterObject(obj, blocked, cacheKey);
      });
      return result;
    };
    scene.userData[`${cacheKey}SceneAddPatched`] = true;
  }

  function _refreshTown() {
    const scene = townDeps?.getTownScene?.(); // Active town scene whose decorative grass must respect authored buildings.
    const mapData = townDeps?.getTownZone?.(); // Active authored town map containing exact building footprint metadata.
    if (!scene || !mapData) return { meshes: 0, source: 0, visible: 0, suppressed: 0 };
    const blocked = authoredBuildingFootprintKeys(mapData); // Exact, unexpanded building footprints; elevation falloff remains grassy.
    _patchSceneAdd(scene, () => authoredBuildingFootprintKeys(townDeps?.getTownZone?.()), 'hobunjiTownBuildingGrass');
    return filterScene(scene, blocked, 'hobunjiTownBuildingGrass');
  }

  function _patchTownZoneBuildings(api) {
    if (!api || api.__hobunjiBuildingGrassPatched) return;
    const originalInit = api.init; // Captured to preserve TownZoneBuildings' existing initialization behavior.
    const originalSpawnTown = api.spawnTownBuildings; // Captured so town grass filtering is an additive post-step.
    const originalSpawnZone = api.spawnZoneBuildings; // Captured so zone grass is filtered once an authored building map is known.
    if (typeof originalInit === 'function') {
      api.init = function (injectedDeps) {
        townDeps = injectedDeps;
        return originalInit.call(this, injectedDeps);
      };
    }
    if (typeof originalSpawnTown === 'function') {
      api.spawnTownBuildings = function (...args) {
        const result = originalSpawnTown.apply(this, args);
        const stats = _refreshTown(); // Building metadata is synchronous even though mesh GLBs finish later.
        if (stats.suppressed) townDeps?.debugLog?.(`Building footprints suppressed ${stats.suppressed} town grass instance(s).`);
        return result;
      };
    }
    if (typeof originalSpawnZone === 'function') {
      api.spawnZoneBuildings = function (mapId, ...args) {
        const result = originalSpawnZone.call(this, mapId, ...args);
        const mapData = townDeps?.zoneLayouts?.get?.(mapId); // Same authored zone layout consumed by TownZoneBuildings itself.
        const sceneRecord = townDeps?.zoneScenes?.get?.(mapId); // Existing zone scene registry supplies the grass-bearing scene.
        const scene = sceneRecord?.scene || sceneRecord;
        if (scene && mapData) {
          const blocked = authoredBuildingFootprintKeys(mapData); // Exact rotated footprint cells, without the subtle-elevation halo.
          const stats = filterScene(scene, blocked, 'hobunjiZoneBuildingGrass');
          if (stats.suppressed) townDeps?.debugLog?.(`Building footprints suppressed ${stats.suppressed} grass instance(s) in ${mapId}.`);
        }
        return result;
      };
    }
    api.refreshBuildingGrassSuppression = _refreshTown;
    api.__hobunjiBuildingGrassPatched = true;
  }

  function _zoneMapForScene(scene) {
    const layouts = zoneDeps?.zoneLayouts; // Zone layout map used to resolve authored building footprints.
    const scenes = zoneDeps?.zoneScenes; // Zone scene registry used to map the scene argument back to its layout id.
    if (scenes?.entries && layouts?.get) {
      for (const [mapId, record] of scenes.entries()) {
        const candidate = record?.scene || record;
        if (candidate === scene) return layouts.get(mapId) || null;
      }
    }
    const mapId = scene?.userData?.mapId || scene?.userData?.zoneId;
    if (mapId && layouts?.get) return layouts.get(mapId) || null;
    if (mapId && layouts && typeof layouts === 'object') return layouts[mapId] || null;
    return null;
  }

  function _patchZoneGrassBillboards(api) {
    if (!api || api.__hobunjiBuildingGrassPatched) return;
    const originalInit = api.init; // Captured to discover zone layout/scene registries without changing game.js callers.
    if (typeof originalInit === 'function') {
      api.init = function (injectedDeps) {
        zoneDeps = injectedDeps;
        return originalInit.call(this, injectedDeps);
      };
    }

    for (const name of ['buildZoneGrassBillboards', 'buildRichFoliageBillboards']) {
      const original = api[name]; // Original builder remains responsible for density, material, and terrain-height placement.
      if (typeof original !== 'function') continue;
      api[name] = function (zScene, ...args) {
        const result = original.call(this, zScene, ...args);
        const mapData = _zoneMapForScene(zScene); // Resolve the same authored map TownZoneBuildings uses for structure placement.
        if (!result || !mapData) return result;
        const blocked = authoredBuildingFootprintKeys(mapData); // Exact zone building cells removed from both ordinary and rich grass.
        filterObject(result, blocked, 'hobunjiZoneBuildingGrass');
        return result;
      };
    }
    api.__hobunjiBuildingGrassPatched = true;
  }

  function _installWhenAssigned(name, patch) {
    const existing = window[name]; // Already-loaded globals are patched immediately (useful in dev-tool dynamic loads).
    if (existing) {
      patch(existing);
      return;
    }
    const descriptor = Object.getOwnPropertyDescriptor(window, name); // Existing configurable descriptor is replaced with a one-time patching accessor.
    if (descriptor && !descriptor.configurable) return;
    let value;
    Object.defineProperty(window, name, {
      configurable: true,
      enumerable: descriptor?.enumerable ?? true,
      get() { return value; },
      set(next) {
        value = next;
        patch(next);
      },
    });
  }

  const api = { // Public helper reused by PlayerHouseElevation for dynamic farmhouse/barn footprints.
    rectFootprintKeys,
    authoredBuildingFootprintKeys,
    filterBillboardMesh,
    filterObject,
    filterScene,
    refreshTown: _refreshTown,
  };
  window.BuildingGrassSuppression = api;

  _installWhenAssigned('TownZoneBuildings', _patchTownZoneBuildings);
  _installWhenAssigned('ZoneGrassBillboards', _patchZoneGrassBillboards);
})();